diff.code:
async function run(consumer) {
  while (true) {
    const batch = await consumer.poll();       // records from N partitions
    await consumer.commit(batch.endOffset);    // commit the whole batch up front
    for (const rec of batch.records) {
      await handle(rec);                        // upsert into the read model
    }
  }
}

// handle() reduces an event into a per-user running total
